<x-app-layout>
<div class="px-4 py-8 sm:px-6"><form method="POST" action="{{ route('driver.vehicles.store') }}" enctype="multipart/form-data" class="mx-auto max-w-5xl rounded-2xl border bg-white p-6" x-data="{
step:1, showPhotoExamples:false, showGeranExample:false, submitting:false, plateCheckBusy:false, uploadNotice:{{ $errors->any() ? 'true' : 'false' }}, clientError:'', accountName:@js(\App\Support\DocumentIdentity::normalizeName(auth()->user()->name)), review:{}, snackbar:{show:false,message:'',timer:null}, ocrBusy:{}, ocrMessage:{}, ocrScanned:{}, ocrProblem:{}, ocrAttempted:{}, vehiclePreviews:{}, documentPreviews:{}, aiVehicleValidationEnabled:{{ config('vehicle_vision.enabled') ? 'true' : 'false' }}, imageValidation:{}, detectedPlates:{}, autoDetectedColour:null,
init(){this.step=1;this.$watch('step',value=>{const normalized=Number(value);if(!Number.isInteger(normalized)||normalized<1||normalized>3)this.step=1})},
currentStep(){const value=Number(this.step);return Number.isInteger(value)&&value>=1&&value<=3?value:1},
fieldsForStep(){return this.currentStep()===1?['front_image','rear_image','side_image','plate_number','colour','seat_capacity']:['vehicle_geran','registered_owner_name','owner_identity_no','manufacturer','model_name']},
async advance(){this.step=this.currentStep();if(this.step===2&&(!this.documentsScanned()||!this.documentDetailsReady()))return;const invalid=this.fieldsForStep().map(n=>this.$root.elements[n]).find(el=>el && !el.checkValidity());if(invalid){if(this.step===2)this.showSnackbar('The scan did not extract all required details. Choose a clearer document and scan it again.');else invalid.reportValidity();return}if(this.step===1 && (!this.vehicleImagesReady() || !await this.plateAvailable()))return;if(this.step===2 && !this.identityReady())return;if(this.step===2)this.prepareReview();this.uploadNotice=false;this.clientError='';this.step=Math.min(3,this.step+1)},
async plateAvailable(){const input=this.$root.elements.plate_number;const body=new FormData();body.append('plate_number',input.value);this.plateCheckBusy=true;try{const response=await fetch('{{ route('driver.vehicles.plate-availability') }}',{method:'POST',headers:{'Accept':'application/json','X-CSRF-TOKEN':document.querySelector('meta[name=csrf-token]').content},body});const data=await response.json();if(!response.ok)throw new Error(data.message||Object.values(data.errors||{})[0]?.[0]||'Unable to check this plate number.');input.value=data.plate_number||input.value;if(!data.available){this.resetVehicleStep();this.showSnackbar(`${data.message} The selected photos and vehicle information were cleared. Please select and validate the vehicle photos again.`);this.$nextTick(()=>this.$root.elements.front_image?.focus());return false}input.setCustomValidity('');return true}catch(error){this.showSnackbar(error.message||'Unable to check this plate number. Please try again.');return false}finally{this.plateCheckBusy=false}},
async submitVehicle(){if(this.submitting||!this.filesReady()||!this.identityReady())return;this.submitting=true;try{const response=await fetch(this.$root.action,{method:'POST',headers:{'Accept':'application/json','X-CSRF-TOKEN':document.querySelector('meta[name=csrf-token]').content},body:new FormData(this.$root)});const data=await response.json().catch(()=>({}));if(!response.ok){const errors=data.errors||{};const firstKey=Object.keys(errors)[0];const stepOneFields=['front_image','rear_image','side_image','front_image_validation_token','rear_image_validation_token','side_image_validation_token','plate_number','colour','seat_capacity'];this.step=stepOneFields.includes(firstKey)?1:2;throw new Error(errors[firstKey]?.[0]||data.message||'Unable to add the vehicle. Review the highlighted information.')}window.location.replace(data.redirect_url||@js(route('driver.vehicles.index', absolute: false)));return}catch(error){this.submitting=false;this.showSnackbar(error.message||'Unable to add the vehicle. Please try again.')}},
goBack(){this.step=Math.max(1,this.step-1)},
prepareReview(){const data={};for(const element of this.$root.elements){if(element.name&&!element.name.endsWith('_validation_token')&&element.type!=='file')data[element.name]=element.value}this.review=data},
filesReady(){const vehicle=['front_image','rear_image','side_image'];if(vehicle.some(n=>!this.$root.elements[n]?.files.length)){this.step=1;this.uploadNotice=true;return false}if(!this.$root.elements.vehicle_geran?.files.length){this.step=2;this.uploadNotice=true;return false}return true},
showSnackbar(message){if(this.snackbar.timer)clearTimeout(this.snackbar.timer);this.snackbar.message=message;this.snackbar.show=true;this.snackbar.timer=setTimeout(()=>this.snackbar.show=false,8000)},
identityReady(){const owner=this.$root.elements.registered_owner_name.value.trim().toUpperCase().replace(/\s+/g,' ');if(owner!==this.accountName){this.clientError=`Geran owner name does not match your driver account name (${this.accountName}). Update your profile to your legal name or upload the correct Geran.`;this.step=2;this.showSnackbar(this.clientError);return false}this.snackbar.show=false;return true},
documentsScanned(){if(!this.ocrScanned.vehicle_geran){this.showSnackbar('Scan and prefill the Vehicle Geran before continuing.');return false}return true},
documentDetailsReady(){const fields={registered_owner_name:'registered owner name',owner_identity_no:'owner IC',manufacturer:'manufacturer',model_name:'model name'};const missing=Object.entries(fields).filter(([field])=>!this.$root.elements[field]?.value.trim()).map(([,label])=>label);this.ocrProblem.vehicle_geran=missing.length>0;this.markDocumentProblem('vehicle_geran',missing.length>0);if(missing.length){this.ocrMessage.vehicle_geran=`Vehicle Geran / VOC image problem: could not read ${missing.join(', ')}. Choose a clearer image and scan it again.`;this.showSnackbar(this.ocrMessage.vehicle_geran);return false}return true},
markDocumentProblem(name,problem){const box=this.$root.elements[name]?.closest('span');['border-red-500','ring-2','ring-red-100'].forEach(className=>box?.classList.toggle(className,problem))},
clearDocumentFields(){['voc_reference_no','owner_identity_no','registered_owner_name','owner_address','chassis_no','engine_no','manufacturer','model_name','engine_capacity','fuel_type','origin_status','usage_class','body_type','manufacturing_year','registration_date','bdm','bgk','btm','registration_condition_1','registration_condition_2','registration_condition_3','brand','model'].forEach(field=>{const input=this.$root.elements[field];if(input)input.value=''})},
previewVehicleImage(name,file){if(!file)return;if(this.autoDetectedColour&&this.$root.elements.colour.value===this.autoDetectedColour)this.$root.elements.colour.value='';this.autoDetectedColour=null;const view={front_image:'FRONT',rear_image:'REAR',side_image:'SIDE'}[name];const previousPlate=this.detectedPlates[view];delete this.detectedPlates[view];if(previousPlate&&this.$root.elements.plate_number.value===previousPlate&&!Object.values(this.detectedPlates).includes(previousPlate))this.$root.elements.plate_number.value='';const previous=this.vehiclePreviews[name]?.url;if(previous)URL.revokeObjectURL(previous);this.vehiclePreviews[name]={url:URL.createObjectURL(file),fileName:file.name};this.imageValidation[name]={busy:false,accepted:false,message:'Photo changed. Validate this image before continuing.',token:null};const token=this.$root.elements[`${name}_validation_token`];if(token)token.value=''},
vehicleImagesReady(){if(!this.aiVehicleValidationEnabled)return true;const missing=['front_image','rear_image','side_image'].filter(name=>!this.imageValidation[name]?.accepted);if(missing.length){this.showSnackbar('Validate the front, rear, and side vehicle photos before continuing.');return false}return true},
resetVehicleStep(){['front_image','rear_image','side_image'].forEach(name=>{const preview=this.vehiclePreviews[name];if(preview?.url)URL.revokeObjectURL(preview.url);const fileInput=this.$root.elements[name];if(fileInput)fileInput.value='';const token=this.$root.elements[`${name}_validation_token`];if(token)token.value=''});['plate_number','brand','model','colour'].forEach(name=>{const input=this.$root.elements[name];if(input)input.value=''});const seats=this.$root.elements.seat_capacity;if(seats)seats.value='4';this.vehiclePreviews={};this.imageValidation={};this.detectedPlates={};this.autoDetectedColour=null;this.step=1},
checkVehicleConsistency(){const accepted=Object.values(this.imageValidation).filter(result=>result?.accepted);const reliable=accepted.filter(result=>result?.colourReliable&&result?.colourGroup);const groups=[...new Set(reliable.map(result=>result.colourGroup))];if(groups.length>1){const visibleColours=[...new Set(reliable.map(result=>result.detectedColour))];const message=`The vehicle colours do not match (${visibleColours.join(' / ')}), so the photos may show different cars. All vehicle information was cleared. Please select front, rear, and side photos of the same vehicle again.`;this.resetVehicleStep();this.showSnackbar(message);return false}if(accepted.length===3){const candidates=accepted.filter(result=>result?.detectedColour);const groupScores={};candidates.forEach(result=>{const group=result.colourGroup||result.detectedColour;groupScores[group]=(groupScores[group]||0)+Number(result.colourConfidence||0)});const winningGroup=Object.entries(groupScores).sort((a,b)=>b[1]-a[1])[0]?.[0];const consensus=candidates.filter(result=>(result.colourGroup||result.detectedColour)===winningGroup).sort((a,b)=>Number(b.colourConfidence||0)-Number(a.colourConfidence||0))[0]?.detectedColour;const input=this.$root.elements.colour;if(consensus&&input){input.value=consensus;this.autoDetectedColour=consensus;input.dispatchEvent(new Event('input',{bubbles:true}))}else{this.showSnackbar('The vehicle colour could not be detected. Choose clearer photos in neutral lighting and validate them again.')}}return true},
applyDetectedPlate(view,plate){if(!plate)return;this.detectedPlates[view]=plate;const readings=[...new Set(Object.values(this.detectedPlates).filter(Boolean))];if(readings.length>1){const message=`The vehicle photos produced different plate readings (${readings.join(' / ')}). All vehicle information was cleared. Please select three photos of the same vehicle again.`;this.resetVehicleStep();this.showSnackbar(message);return}const input=this.$root.elements.plate_number;input.value=plate;input.dispatchEvent(new Event('input',{bubbles:true}))},
async validateVehicleImage(name,view){const file=this.$root.elements[name]?.files[0];if(!file){this.showSnackbar('Choose a vehicle photo first.');return}this.imageValidation[name]={busy:true,accepted:false,message:'Checking this photo locally and reading the plate…',token:null};const body=new FormData();body.append('image',file);body.append('expected_view',view);try{const response=await fetch('{{ route('driver.vehicles.images.validate') }}',{method:'POST',headers:{'Accept':'application/json','X-CSRF-TOKEN':'{{ csrf_token() }}'},body});const data=await response.json();if(!response.ok)throw new Error(Object.values(data.errors||{})[0]?.[0]||data.message||'Unable to validate photo.');this.imageValidation[name]={busy:false,accepted:data.accepted,message:data.message+(data.accepted&&!data.plate_number?' No clear plate number was found in this photo.':''),token:data.token,detectedColour:data.detected_colour,colourGroup:data.colour_group||data.detected_colour,colourConfidence:data.colour_confidence,colourReliable:data.colour_reliable};this.$root.elements[`${name}_validation_token`].value=data.token||'';if(data.accepted){if(this.checkVehicleConsistency())this.applyDetectedPlate(view,data.plate_number)}else this.showSnackbar(data.message||`The ${view.toLowerCase()} photo was not accepted.`)}catch(error){this.imageValidation[name]={busy:false,accepted:false,message:error.message,token:null};this.showSnackbar(error.message)}},
previewDocument(name,file){if(!file)return;this.clearDocumentFields(name);const previous=this.documentPreviews[name]?.url;if(previous)URL.revokeObjectURL(previous);this.documentPreviews[name]={url:URL.createObjectURL(file),fileName:file.name};this.ocrMessage[name]='Ready to scan. This may take up to one minute on the first attempt.';this.ocrScanned[name]=false;this.ocrProblem[name]=false;this.ocrAttempted[name]=false;this.markDocumentProblem(name,false)},
dateValue(value){const match=(value||'').match(/^(\d{2})[\/.\-](\d{2})[\/.\-](\d{4})$/);return match?`${match[3]}-${match[2]}-${match[1]}`:value},
applyOcr(type,fields){const map={voc_reference_no:'voc_reference_no',registration_no:'plate_number',owner_identity_no:'owner_identity_no',registered_owner_name:'registered_owner_name',owner_address:'owner_address',chassis_no:'chassis_no',engine_no:'engine_no',manufacturer:'manufacturer',model_name:'model_name',engine_capacity:'engine_capacity',fuel_type:'fuel_type',origin_status:'origin_status',usage_class:'usage_class',body_type:'body_type',manufacturing_year:'manufacturing_year',registration_date:'registration_date',bdm:'bdm',bgk:'bgk',btm:'btm',registration_condition_1:'registration_condition_1',registration_condition_2:'registration_condition_2',registration_condition_3:'registration_condition_3'};Object.entries(map).forEach(([source,target])=>{const value=fields[source]?.value;const input=this.$root.elements[target];if(input&&value!==null&&value!==undefined&&value!=='')input.value=input.type==='date'?this.dateValue(value):value});this.$root.elements.brand.value=this.$root.elements.manufacturer.value;this.$root.elements.model.value=this.$root.elements.model_name.value},
async scanDocument(inputName,type){const file=this.$root.elements[inputName]?.files[0];if(!file){this.ocrMessage[inputName]='Choose a Vehicle Geran image first.';this.showSnackbar(this.ocrMessage[inputName]);return}this.ocrProblem[inputName]=false;this.ocrAttempted[inputName]=true;this.markDocumentProblem(inputName,false);this.ocrScanned[inputName]=false;this.ocrBusy[inputName]=true;this.ocrMessage[inputName]='Scanning your document… The first scan may take up to five minutes.';const body=new FormData();body.append('document',file);body.append('expected_document_type',type);const controller=new AbortController();const timeout=setTimeout(()=>controller.abort(),310000);try{const response=await fetch('{{ route('driver.vehicles.documents.ocr') }}',{method:'POST',headers:{'Accept':'application/json','X-CSRF-TOKEN':'{{ csrf_token() }}'},body,signal:controller.signal});const data=await response.json();if(!response.ok)throw new Error(data.message||Object.values(data.errors||{})[0]?.[0]||'Unable to scan document.');this.applyOcr(type,data.fields);this.ocrScanned[inputName]=true;this.ocrMessage[inputName]='Scan complete. Continue to review the extracted details.'}catch(error){this.ocrProblem[inputName]=true;this.markDocumentProblem(inputName,true);this.ocrScanned[inputName]=false;this.ocrMessage[inputName]=error.name==='AbortError'?'Scanning took too long. Please retry with a smaller, clearer image.':(error.message||'Unable to scan this document.');this.showSnackbar(this.ocrMessage[inputName])}finally{clearTimeout(timeout);this.ocrBusy[inputName]=false}}
}" @submit.prevent="submitVehicle()">
