text="imageValidation['{{ $name }}']?.accepted?'Validate again':'Validate photo'"></button><p x-show="imageValidation['{{ $name }}']?.message && !imageValidation['{{ $name }}']?.busy" x-text="imageValidation['{{ $name }}']?.message" :class="imageValidation['{{ $name }}']?.accepted?'text-green-700':'font-medium text-red-700'" class="mt-2 text-sm" role="status"></p></div></template>@error($name)<span class="mt-1 block text-sm text-red-600">{{ $message }}</span>@enderror</div>@endforeach</div>
